(() => {
'use strict';
const $ = id => document.getElementById(id);
const films = window.FILMS || [];
const meta = window.FILM_META || {};
if (meta.imdbCheckedAt) {
  const dateNote = document.querySelector('.date-note');
  if (dateNote) dateNote.innerHTML = `IMDb 核对日期 <b>${String(meta.imdbCheckedAt).replace(/[^0-9-]/g,'')}</b><br><span>其他资料截至 ${String(meta.accessedAt || '').replace(/[^0-9-]/g,'')}</span>`;
}
const safe = v => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const link = u => /^https?:\/\//i.test(u || '') ? safe(u) : '#';
const coverLink = u => /^(?:posters\/tt\d+\.(?:jpe?g|png|webp)$|https?:\/\/)/i.test(u || '') ? safe(u) : '';
const list = v => Array.isArray(v) ? v : v ? [v] : [];
const score = r => typeof r?.score === 'number' ? r.score : null;
const n = v => Number(v || 0).toLocaleString('zh-CN');
const gross = v => !v ? '待核实' : v >= 1e8 ? `$${(v / 1e8).toFixed(2)} 亿` : `$${(v / 1e4).toFixed(0)} 万`;
const ids = ['year-from','year-to','genre','country','reason','imdb-min','douban-min','gross-min','dual','awarded','complete'];
let saved = new Set();
try { saved = new Set(JSON.parse(localStorage.getItem('film-atlas-saved') || '[]')); } catch {}
let page = 1, preset = 'all', view = 'grid', currentFilms = [], toastTimer;
const pageSize = 48;
const featured = ['肖申克的救赎','星际穿越','霸王别姬','千与千寻','盗梦空间','泰坦尼克号','寄生虫','阿凡达','机器人总动员','楚门的世界','无间道','美丽人生','指环王3：王者无敌','辛德勒的名单','三傻大闹宝莱坞','疯狂动物城','黑客帝国','阿甘正传','海上钢琴师','花样年华','奥本海默','寻梦环游记','让子弹飞','饮食男女'];
function options(id, values) { $(id).insertAdjacentHTML('beforeend', values.map(v => `<option value="${safe(v)}">${safe(v)}</option>`).join('')); }
const years = Array.from({length:39},(_,i)=>1988+i);
options('year-from',years); options('year-to',years); $('year-from').value='1988'; $('year-to').value='2026';
options('genre',[...new Set(films.flatMap(f=>list(f.genres)))].sort((a,b)=>a.localeCompare(b,'zh')));
options('country',[...new Set(films.flatMap(f=>list(f.countries)))].sort((a,b)=>a.localeCompare(b,'zh')));
options('reason',[...new Set(films.flatMap(f=>list(f.reasons)))].sort((a,b)=>a.localeCompare(b,'zh')));
$('total-count').textContent=n(films.length); $('country-count').textContent=new Set(films.flatMap(f=>list(f.countries))).size;
const params = new URLSearchParams(location.search);
for(const id of [...ids,'search','sort']) {if(params.has(id)){if($(id).type==='checkbox') $(id).checked=params.get(id)==='1'; else if($(id).tagName!=='SELECT'||[...$(id).options].some(o=>o.value===params.get(id))) $(id).value=params.get(id);}}
if(['all','classic','boxoffice','world','animation','saved'].includes(params.get('preset'))) preset=params.get('preset');
if(params.get('view')==='list') view='list';
function state(){return {q:$('search').value.trim().toLocaleLowerCase(),from:+$('year-from').value,to:+$('year-to').value,genre:$('genre').value,country:$('country').value,reason:$('reason').value,imdb:+$('imdb-min').value,douban:+$('douban-min').value,gross:+$('gross-min').value,dual:$('dual').checked,awarded:$('awarded').checked,complete:$('complete').checked};}
function matches(f,s){
  if(f.year<s.from||f.year>s.to) return false;
  if(s.q&&!([f.title,f.originalTitle,...list(f.directors),...list(f.cast),...list(f.castAliases),...list(f.directorAliases),...list(f.aliases)].join(' ').toLocaleLowerCase().includes(s.q)))return false;
  if(s.genre&&!list(f.genres).includes(s.genre)||s.country&&!list(f.countries).includes(s.country)||s.reason&&!list(f.reasons).includes(s.reason))return false;
  if(s.imdb&&(score(f.imdb)===null||score(f.imdb)<s.imdb)||s.douban&&(score(f.douban)===null||score(f.douban)<s.douban))return false;
  if(s.gross&&(!f.boxOffice?.comparable||f.boxOffice.usd<s.gross)||s.dual&&(score(f.imdb)===null||score(f.douban)===null)||s.awarded&&!list(f.awards).length)return false;
  if(s.complete&&f.metadataPending)return false;
  if(preset==='saved'&&!saved.has(f.id))return false;
  if(preset==='classic'&&!((score(f.imdb)>=7&&f.imdb?.votes>=5000)||(score(f.douban)>=7.5&&f.douban?.votes>=5000)))return false;
  if(preset==='boxoffice'&&!(f.boxOffice?.comparable&&f.boxOffice.usd>=5e8))return false;
  if(preset==='animation'&&!list(f.genres).includes('动画'))return false;
  if(preset==='world'&&!list(f.countries).some(c=>!['美国','英国','加拿大','澳大利亚','新西兰'].includes(c)))return false;
  return true;
}
function sortFilms(items){const mode=$('sort').value;const rank=f=>{const i=featured.indexOf(f.title);return i<0?10000-(score(f.imdb)||0)*20-(score(f.douban)||0)*10:i;};return items.sort((a,b)=>{if(mode==='yearAsc')return a.year-b.year||rank(a)-rank(b);if(mode==='yearDesc')return b.year-a.year||rank(a)-rank(b);if(mode==='imdb')return (score(b.imdb)??-1)-(score(a.imdb)??-1)||(b.imdb?.votes||0)-(a.imdb?.votes||0);if(mode==='douban')return(score(b.douban)??-1)-(score(a.douban)??-1)||(b.douban?.votes||0)-(a.douban?.votes||0);if(mode==='gross')return(b.boxOffice?.comparable?b.boxOffice.usd:0)-(a.boxOffice?.comparable?a.boxOffice.usd:0);if(mode==='title')return a.title.localeCompare(b.title,'zh');return rank(a)-rank(b)||b.year-a.year;});}
function poster(f){const palettes=[['#3d4934','#16231f'],['#694b35','#281e24'],['#344554','#132a32'],['#76534b','#2c2536'],['#5c6350','#283329'],['#746747','#332c25']];let hash=0;for(const c of f.title)hash=(hash+c.charCodeAt(0))%palettes.length;const p=palettes[hash];return `<div class="poster"><div class="poster-fallback" style="--poster-a:${p[0]};--poster-b:${p[1]}"><small>${f.posterLocal?'THE FILM ATLAS':'封面待补'} / ${f.year}</small><strong>${safe(f.originalTitle||f.title)}</strong><span class="year-art">${safe(f.title)}</span></div>${f.poster?`<img src="${coverLink(f.poster)}" alt="${safe(f.title)} 海报" loading="lazy" referrerpolicy="no-referrer" style="position:absolute;inset:0" onerror="this.remove()">`:''}<span class="poster-tag">${safe(f.metadataPending?'资料待补全':list(f.reasons)[0]||'世界电影')}</span><span class="poster-year">${f.year}</span></div>`;}
function rating(r,kind){const v=score(r);return `<span class="rating ${kind} ${v===null?'missing':''}"><em>${kind==='imdb'?'IMDb':'豆'}</em><b>${v===null?'待核实':v.toFixed(1)}</b></span>`;}
function card(f){return `<article class="film-card"><button class="card-open" data-open="${safe(f.id)}" aria-label="查看${safe(f.title)}详情">${poster(f)}<h3 class="card-title">${safe(f.title)}</h3><p class="card-original">${safe(f.originalTitle)}</p><p class="card-meta">${safe(list(f.countries).slice(0,2).join(' / ')||'地区待补核')} · ${safe(list(f.genres).slice(0,2).join(' / '))}</p><div class="ratings">${rating(f.imdb,'imdb')}${rating(f.douban,'douban')}<span class="gross-caption">${f.boxOffice?.usd?gross(f.boxOffice.usd):''}</span></div></button><button class="bookmark ${saved.has(f.id)?'saved':''}" data-save="${safe(f.id)}" aria-label="${saved.has(f.id)?'移出':'加入'}片单：${safe(f.title)}" aria-pressed="${saved.has(f.id)}">${saved.has(f.id)?'♥':'♡'}</button></article>`;}
function table(items){return `<div class="table-wrap"><table class="film-table"><thead><tr><th>电影</th><th>年份</th><th>类型 / 地区</th><th>IMDb</th><th>豆瓣</th><th>票房（美元）</th></tr></thead><tbody>${items.map(f=>`<tr><td><button class="table-title" data-open="${safe(f.id)}">${safe(f.title)}<small>${safe(f.originalTitle)}</small></button></td><td>${f.year}</td><td class="table-meta">${safe(list(f.genres).slice(0,2).join(' / '))}<br>${safe(list(f.countries).join(' / '))}</td><td>${score(f.imdb)?.toFixed(1)||'待核实'}</td><td>${score(f.douban)?.toFixed(1)||'待核实'}</td><td>${gross(f.boxOffice?.usd)}${f.boxOffice?.usd&&!f.boxOffice.comparable?'<br><small>全球口径待复核</small>':''}</td></tr>`).join('')}</tbody></table></div>`;}
function urlUpdate(){const p=new URLSearchParams();for(const id of [...ids,'search','sort']){const el=$(id),v=el.type==='checkbox'?(el.checked?'1':''):el.value;if(v&&!(id==='year-from'&&v==='1988')&&!(id==='year-to'&&v==='2026')&&!(id==='sort'&&v==='recommended')&&!(['imdb-min','douban-min','gross-min'].includes(id)&&v==='0'))p.set(id,v);}if(preset!=='all')p.set('preset',preset);if(view!=='grid')p.set('view',view);try{history.replaceState(null,'',location.pathname+(p.size?'?'+p.toString():'')+location.hash);}catch{}}
function render(){const s=state();$('imdb-output').textContent=s.imdb?s.imdb.toFixed(1)+'+':'不限';$('douban-output').textContent=s.douban?s.douban.toFixed(1)+'+':'不限';currentFilms=sortFilms(films.filter(f=>matches(f,s)));const pages=Math.max(1,Math.ceil(currentFilms.length/pageSize));page=Math.min(page,pages);const items=currentFilms.slice((page-1)*pageSize,page*pageSize);$('result-count').textContent=n(currentFilms.length);$('result-context').textContent=`${s.from}—${s.to}`;$('saved-count').textContent=saved.size;document.querySelectorAll('[data-preset]').forEach(b=>b.classList.toggle('active',b.dataset.preset===preset));for(const id of ['grid','list']){$(id+'-view').classList.toggle('selected',view===id);$(id+'-view').setAttribute('aria-pressed',view===id);}
const tags=[s.q&&`搜索：${s.q}`,s.genre,s.country,s.reason,s.imdb&&`IMDb ≥ ${s.imdb}`,s.douban&&`豆瓣 ≥ ${s.douban}`,s.gross&&`票房 ≥ ${gross(s.gross)}`,s.dual&&'双平台评分',s.awarded&&'已记录获奖',s.complete&&'人物地区资料完整'].filter(Boolean);$('active-filters').innerHTML=tags.map(t=>`<span>${safe(t)}</span>`).join('');$('results').className=view==='grid'?'film-grid':'';
$('results').innerHTML=items.length?(view==='grid'?items.map(card).join(''):table(items)):`<div class="empty"><span>◒</span><h3>${preset==='saved'?'你的片单，等待第一部好电影':'还没有符合条件的电影'}</h3><p>${preset==='saved'?'点击电影卡片上的爱心，把想看的电影留在这里。<br>片单只保存在当前浏览器中。':'试试放宽年份、评分或地区条件。<br>待核实数据不会通过相应的数值筛选。'}</p><button data-reset>浏览全部电影</button></div>`;
let nums=[1,pages];for(let i=Math.max(1,page-2);i<=Math.min(pages,page+2);i++)nums.push(i);nums=[...new Set(nums)].sort((a,b)=>a-b);let prev=0;const buttons=nums.map(i=>{const sep=i-prev>1?'<span>…</span>':'';prev=i;return sep+`<button data-page="${i}" class="${i===page?'current':''}" ${i===page?'aria-current="page"':''}>${i}</button>`;}).join('');$('pagination').innerHTML=items.length?`<button data-page="${page-1}" ${page===1?'disabled':''} aria-label="上一页">←</button>${buttons}<button data-page="${page+1}" ${page===pages?'disabled':''} aria-label="下一页">→</button><span>共 ${pages} 页</span>`:'';urlUpdate();}
function notify(msg){$('toast').textContent=msg;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),2300);}
function toggleSave(id){if(saved.has(id))saved.delete(id);else saved.add(id);try{localStorage.setItem('film-atlas-saved',JSON.stringify([...saved]));}catch{notify('浏览器无法保存片单；本次浏览仍可使用。');}render();if($('detail-dialog').open){const b=$('detail-content').querySelector('[data-save]');if(b){b.textContent=saved.has(id)?'♥ 已加入片单':'♡ 加入我的片单';b.setAttribute('aria-pressed',saved.has(id));}}}
function external(url,label){return `<a href="${link(url)}" target="_blank" rel="noopener noreferrer">${safe(label)} ↗</a>`;}
function detail(id){const f=films.find(f=>f.id===id);if(!f)return;const r=(val,name)=>`<a href="${link(val?.url||'https://www.imdb.com/')}" target="_blank" rel="noopener noreferrer"><span>${name} ↗</span><strong>${score(val)?.toFixed(1)||'—'}</strong><small>${score(val)!==null?(val.votes?n(val.votes)+' 人评价':'评价人数待补核'):'评分待核实'}${val?.checkedAt?'<br>核对 '+safe(val.checkedAt):''}${val?.sourceDate?'<br>来源快照 '+safe(val.sourceDate):''}</small></a>`;const awards=list(f.awards);$('detail-content').innerHTML=`<div class="dialog-header"><span class="eyebrow">FILM NO. ${safe(f.id)} / ${f.year}</span><button class="close-dialog" data-close aria-label="关闭详情">×</button></div><div class="detail-main"><div class="detail-art">${poster(f)}</div><div><div class="detail-title"><h2>${safe(f.title)}</h2><p>${safe(f.originalTitle)}</p></div><div class="tag-list">${[...list(f.genres),...list(f.reasons)].map(t=>`<span>${safe(t)}</span>`).join('')}</div><div class="detail-ratings">${r(f.imdb,'IMDb')}${r(f.douban,'豆瓣电影')}</div><dl class="detail-facts"><dt>年份</dt><dd>${f.year} · ${safe(f.status||'已上映')}${f.releaseYearNote?`<small>${safe(f.releaseYearNote)}</small>`:''}</dd><dt>国家/地区</dt><dd>${safe(list(f.countries).join(' / ')||'待补核')}</dd><dt>导演</dt><dd>${safe(list(f.directors).join(' / ')||'待补核')}</dd><dt>主演</dt><dd>${safe(list(f.cast).join(' / ')||'待补核')}</dd><dt>票房</dt><dd>${gross(f.boxOffice?.usd)}${f.boxOffice?.usd?`<small>${n(f.boxOffice.usd)} 美元 · ${safe(f.boxOffice.scope||'全球累计')} · 未经通胀调整</small>`:''}${f.boxOffice?.note?`<small>${safe(f.boxOffice.note)}</small>`:''}${f.boxOffice?.url?external(f.boxOffice.url,'票房来源'):''}</dd><dt>入选依据</dt><dd>${safe(list(f.inclusion?.rules).join('；')||(f.legacySelection?'原精选保留：票房、口碑、奖项或地区代表':list(f.reasons).join(' / ')))}</dd><dt>主要荣誉</dt><dd>${awards.length?awards.map(a=>typeof a==='string'?safe(a):`${safe(a.text)} ${a.url?external(a.url,'来源'):''}`).join('<br>'):'待补核（不代表未获奖）'}</dd>${f.awardsSummary?`<dt>奖项汇总</dt><dd>${safe(f.awardsSummary.text)}<small>${safe(f.awardsSummary.note)}</small>${external(f.awardsSummary.url,'汇总来源')}</dd>`:''}</dl><div class="detail-actions"><button data-save="${safe(id)}" aria-pressed="${saved.has(id)}">${saved.has(id)?'♥ 已加入片单':'♡ 加入我的片单'}</button>${f.imdb?.url?external(f.imdb.url,'IMDb 影片页'):''}${f.douban?.url?external(f.douban.url,'豆瓣影片页'):''}</div></div></div><div class="detail-sources"><h3>资料与来源</h3>${list(f.sources).filter(s=>s.url).map(s=>external(s.url,s.label)).join('')}<p>资料整理日期：${safe(meta.accessedAt||'2026-11-01')}。各平台评分核对日期见评分卡。${f.year===2026?'2026 年数据为年内快照，票房可能继续变化。':''}评分以可访问的来源快照为准，不代表实时值。海报与影片资料版权归各权利人；封面优先读取本地图片；仍缺失时显示文字封面。${f.metadataPending?'本片已有影片身份及评分／票房依据，部分人物与地区资料仍待补核。':''}</p></div>`;$('detail-dialog').showModal();}
function showInfo(title,html){$('info-content').innerHTML=`<div class="dialog-header"><h2>${safe(title)}</h2><button class="close-dialog" data-close aria-label="关闭">×</button></div><div class="info-body">${html}</div>`;$('info-dialog').showModal();}
function method(){const a=films.filter(f=>score(f.imdb)!==null).length,b=films.filter(f=>score(f.douban)!==null).length,g=films.filter(f=>f.boxOffice?.comparable).length,w=films.filter(f=>list(f.awards).length).length;showInfo('一份可以追溯，也可以继续生长的电影年鉴',`<p>覆盖 1988—2026 年，已取消每年收录数量上限，采用票房、评分、重要奖项三类条件的并集，兼顾商业影响力、长期口碑、电影节与各地区作品。目前共 ${n(films.length)} 部。原版 886 部采用每年 20–30 部的人工精选，存在明显遗漏。新版按公开数据批量扩充；评分和票房候选先核实影片身份、年份再入库。各数据来源仍有覆盖缺口，不等于全世界所有达标影片都已收齐。</p><h3>当前收录标准（满足任一条）</h3><ul><li>票房代表：年度全球票房榜前 100。保留榜单年份和原始排名；影片按首次首映年份归档，重映条目不重复计数。</li><li>评分门槛：IMDb ≥ 7.0，或豆瓣 ≥ 7.5；达到门槛的平台至少有 5,000 人评价。两平台评分不要求同时达标。</li><li>奖项门槛：奥斯卡及戛纳、柏林、威尼斯等重要电影奖项获奖作品；原精选影片保留。新增批量记录保存入选依据，未取得的导演、演员、票房或奖项明确标为待补核。</li></ul><p>“高分佳作”快捷筛选采用可验证门槛：IMDb ≥ 7.0 且至少 5,000 人评价，或豆瓣 ≥ 7.5 且至少 5,000 人评价；“票房大片”采用来源已报告的全球票房 ≥ 5 亿美元；全球口径待复核的金额不通过票房门槛。“世界视野”显示至少含一个美国、英国、加拿大、澳大利亚、新西兰以外制作国家/地区的作品。</p><h3>已核实到哪一步？</h3><p>IMDb 评分 ${n(a)} / ${n(films.length)}，豆瓣评分 ${n(b)} / ${n(films.length)}，可比较的全球美元票房 ${n(g)} / ${n(films.length)}，已记录主要荣誉 ${n(w)} 部。本地真实封面 ${n(meta.localPosters||0)} / ${n(films.length)}，人物及地区资料完整 ${n(meta.metadataComplete||0)} / ${n(films.length)}。未取得中文名的影片保留原名，可按英文名搜索。缺失显示“待核实”，不填写估计评分、不用零票房替代缺失值。缺失数值不通过对应数值筛选。部分资料页虽记录金额，全球统计范围尚待复核，详情及表格会作标注；这些金额不参与全球票房门槛和排名。</p><h3>本次检索的实际覆盖</h3><p>IMDb 官方数据中符合当前年份、影片类型、评分及票数门槛的 ${n(meta.discoveryCoverage?.imdbQualified||0)} 部已按 ID 纳入。年度票房榜共 ${n(meta.discoveryCoverage?.annualChartRows||0)} 条，其中 ${n(meta.discoveryCoverage?.annualChartMatchedRows||0)} 条已匹配电影身份；其余包含重映、年代外影片及尚未唯一匹配的条目。豆瓣已取得的类型榜单中有 ${n(meta.discoveryCoverage?.doubanCachedQualified||0)} 条达到分数和票数门槛，其中 ${n(meta.discoveryCoverage?.doubanVerified||0)} 部通过电影身份与年份核对。未通过唯一匹配的候选不强行入库，现有来源也不覆盖豆瓣全部电影。</p><h3>评分、票房与年份的口径</h3><ul><li>IMDb：优先使用 ${external('https://datasets.imdbws.com/','官方每日公开数据集')}，保留平均分、评价人数与影片 IMDb ID。${meta.imdbSourceDate?'本次取得的数据快照日期：'+safe(meta.imdbSourceDate)+'。':''}</li><li>人物、地区与封面：新增批量条目按 IMDb ID 与 Cinemeta 公开元资料精确关联；原片库保留逐片核对的来源，封面保存为本地图片。电影年份以 IMDb 首次发行或已核对首映年份为准，可能与某一地区的上映年份不同。</li><li>豆瓣：来自可访问的 ${external('https://movie.douban.com/top250','豆瓣榜单')}、公开类型榜单与站内搜索结果；部分影片尚未补核。每个平台分别展示，不计算混合总分。</li><li>票房：各影片附具体来源，优先公开票房资料与引用它们的影片资料页。以全球累计、美元计价、未调整通胀为比较口径；当地币种、租金、范围值或无法确认全球范围的数据保留说明，不混入美元排序。部分来源可能含重映收入，累计值也可能更新。</li><li>年份：按首次公开发行或首映年份归档，可能早于中国上映、其他地区公映和颁奖年份；有争议时在影片详情注明。</li><li>国家/地区采用制作地信息，可含合拍地区；动画“主演”包括配音演员。荣誉只列已核实的部分重要奖项，空白不表示没有获奖。</li></ul><h3>2026 年与更新日期</h3><p>本次整理截至 2026 年 11 月 1 日。2026 年无法提前形成截至 12 月 31 日的完整评分、票房和年度获奖记录。本库仅展示当前可核实资料，年终结果待 2027 年再补齐。访问日期不等于每个来源的更新时间；${meta.imdbCheckedAt?'已有影片的 IMDb 评分最近核对于 '+safe(meta.imdbCheckedAt)+'；豆瓣、票房、奖项和新增影片仍需另行补核。已入库影片保留历史入选依据，当前高分筛选使用最新分数。':'当前为静态快照；配置 GitHub Actions 后可定时更新已有影片的 IMDb 评分。豆瓣、票房、奖项和新增影片仍需另行补核。'}</p><h3>片单与导出</h3><p>片单存储于本浏览器，清除浏览器数据会移除片单。导出 CSV 包含当前所有筛选结果及来源，适合继续整理和补核；不会只导出当前一页。</p>`);}
function coverage(){const rows=years.map(y=>{const a=films.filter(f=>f.year===y);return `<tr><td>${y}${y===2026?' · 年内':''}</td><td>${a.length}</td><td>${a.filter(f=>score(f.imdb)!==null).length}</td><td>${a.filter(f=>score(f.douban)!==null).length}</td><td>${a.filter(f=>f.boxOffice?.comparable).length}</td><td>${a.filter(f=>f.posterLocal).length}</td><td><button data-year="${y}">浏览 →</button></td></tr>`;}).join('');showInfo('逐年收录与数据覆盖',`<p>已取消每年数量上限。下列评分和票房数量仅统计已核实数值，便于判断完整度。2026 年为截至 11 月 1 日的年内资料。</p><div class="table-wrap"><table class="coverage-table"><thead><tr><th>年份</th><th>收录</th><th>IMDb</th><th>豆瓣</th><th>全球口径票房</th><th>本地封面</th><th></th></tr></thead><tbody>${rows}</tbody></table></div>`);}
function reset(){for(const id of ids){const e=$(id);if(e.type==='checkbox')e.checked=false;else e.value=id==='year-from'?'1988':id==='year-to'?'2026':e.type==='range'||id==='gross-min'?'0':'';}$('search').value='';$('sort').value='recommended';preset='all';page=1;render();}
function csvExport(){const headers=['片名','原名','年份','类型','国家/地区','导演','主演','IMDb评分','IMDb评价人数','豆瓣评分','豆瓣评价人数','来源所载票房_USD','可参与全球票房比较','票房口径','票房说明','主要荣誉','入选理由','入选依据','IMDb来源','豆瓣来源','票房来源','其他来源','资料整理日期','IMDb核对日期','豆瓣核对日期'];const rows=currentFilms.map(f=>[f.title,f.originalTitle,f.year,list(f.genres).join(' / '),list(f.countries).join(' / '),list(f.directors).join(' / '),list(f.cast).join(' / '),score(f.imdb),f.imdb?.votes,score(f.douban),f.douban?.votes,f.boxOffice?.usd,f.boxOffice?.comparable?'是':'否',f.boxOffice?.scope,f.boxOffice?.note,list(f.awards).map(a=>typeof a==='string'?a:a.text).join('；'),list(f.reasons).join(' / '),list(f.inclusion?.rules).join('；'),f.imdb?.url,f.douban?.url,f.boxOffice?.url,list(f.sources).map(s=>s.url).join(' | '),meta.accessedAt||'2026-11-01',f.imdb?.checkedAt,f.douban?.checkedAt]);const escapeCell=v=>{let s=String(v??'');if(/^[=+@\-\t\r]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';};const csv='\uFEFF'+[headers,...rows].map(r=>r.map(escapeCell).join(',')).join('\r\n');const u=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'}));const a=document.createElement('a');a.href=u;a.download=`银幕年鉴_${currentFilms.length}部_${meta.dataUpdatedAt||meta.accessedAt||'2026-11-01'}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);notify(`已导出 ${currentFilms.length} 部电影`);}
document.addEventListener('click',e=>{const t=e.target.closest('button');if(!t)return;if(t.dataset.open)detail(t.dataset.open);if(t.dataset.save)toggleSave(t.dataset.save);if(t.hasAttribute('data-close'))t.closest('dialog').close();if(t.hasAttribute('data-reset'))reset();if(t.dataset.preset){preset=t.dataset.preset;page=1;render();}if(t.dataset.page){page=+t.dataset.page;render();$('library').scrollIntoView({behavior:'smooth'});}if(t.dataset.year){reset();$('year-from').value=t.dataset.year;$('year-to').value=t.dataset.year;$('info-dialog').close();render();$('library').scrollIntoView({behavior:'smooth'});}});
let searchTimer; $('search').addEventListener('input',()=>{clearTimeout(searchTimer);searchTimer=setTimeout(()=>{page=1;render();},150);});
for(const id of ids)$(id).addEventListener($(id).type==='range'?'input':'change',()=>{if(id==='year-from'&&+$('year-from').value>+$('year-to').value)$('year-to').value=$('year-from').value;if(id==='year-to'&&+$('year-to').value<+$('year-from').value)$('year-from').value=$('year-to').value;page=1;render();});
$('sort').addEventListener('change',()=>{page=1;render();});for(const v of ['grid','list'])$(v+'-view').onclick=()=>{view=v;render();};$('reset').onclick=reset;$('method-open').onclick=method;$('method-bottom').onclick=method;$('coverage-open').onclick=coverage;$('saved-nav').onclick=()=>{preset='saved';page=1;render();$('library').scrollIntoView({behavior:'smooth'});};$('export').onclick=csvExport;
for(const d of document.querySelectorAll('dialog'))d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}});
document.addEventListener('keydown',e=>{if(e.key==='/'&&!/INPUT|TEXTAREA|SELECT/.test(document.activeElement.tagName)&&!document.querySelector('dialog[open]')){e.preventDefault();$('search').focus();}});
render();
})();
